SELECT ic.id, ic.number, ic.type, ic.sub_type, ic.create_time, ic.oper_time, ic.organ_id, ic.creator, ic.depot_id, ic.status, ic.total_amount, ic.remark, ic.delete_flag, ic.tenant_id, ic.link_number, o.name AS organName, u.username AS creatorName, d.name AS depotName, IFNULL(DATE_FORMAT(ic.oper_time,'%Y-%m-%d %H:%i:%S'),'') AS operTimeStr, (SELECT COUNT(1) FROM jsh_inventory_check_item ici WHERE ici.header_id = ic.id AND IFNULL(ici.delete_flag,'0') = '0') AS itemCount, GROUP_CONCAT(DISTINCT CONCAT(m.name,' ',IFNULL(m.model,'')) SEPARATOR ', ') AS materialsList FROM jsh_inventory_check ic LEFT JOIN jsh_organization o ON ic.organ_id = o.id AND IFNULL(o.delete_flag,'0') = '0' LEFT JOIN jsh_user u ON ic.creator = u.id AND IFNULL(u.delete_flag,'0') = '0' LEFT JOIN jsh_depot d ON ic.depot_id = d.id AND IFNULL(d.delete_flag,'0') = '0' LEFT JOIN jsh_inventory_check_item ici ON ic.id = ici.header_id AND IFNULL(ici.delete_flag,'0') = '0' LEFT JOIN jsh_material m ON ici.material_id = m.id AND IFNULL(m.delete_flag,'0') = '0' WHERE 1=1 AND IFNULL(ic.delete_flag,'0') = '0'
AND ic.type = #{type}
AND ic.sub_type = #{subType}
AND ic.number LIKE CONCAT('%', #{number}, '%')
AND ic.link_number LIKE CONCAT('%', #{linkNumber}, '%')
AND ic.create_time >= #{beginTime}
AND ic.create_time <= #{endTime}
AND m.name LIKE CONCAT('%', #{materialParam}, '%')
AND ic.depot_id IN (${depotList})
AND ic.creator IN
#{creator}
AND ic.status IN
#{status}
AND ic.remark LIKE CONCAT('%', #{remark}, '%')
GROUP BY ic.id ORDER BY ic.id DESC
LIMIT #{offset}, #{rows}

